INSERT INTO posts (id, title, slug, content, excerpt, featured_image, author_id, status, is_featured, view_count, published_at, created_at, updated_at) VALUES (2, 'Sát Thủ Đại Dương: Cơn Ác Mộng Trỗi Dậy – Bom Tấn Kinh Dị Hot Nhất Tuần Này!', 'sat-thu-ai-duong-con-ac-mong-troi-day-bom-tan-kinh-di-hot-nhat-tuan-nay', '<p><strong>Đại dương chưa bao giờ đáng sợ đến thế!</strong></p><p>&nbsp;</p><p><a href="https://dash.cloudflare.com/login/google?oidcJwt=eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCIsImtpZCI6IndMbVBMR2puc0RTRWFiMGk5RGQ5SXFEbXdiaVA2Y0xVRDN0ZC1aVmo0TTAifQ..B9sCX3rsbzu7H80rYBtBMUEn-NOix4SWVtKbnnsgM8oUw_Ea5M-Ix0xXKaWYYEjIl0w5IXpqdUmwKOXT-eOS25cn2rNZTkFVqCtY--0cLR1XFeTG6kpbJAHm104VBbnifTuAA1qObzoxImCx3kmHjqIwtPIN0NV5ebCHuPDVsJnW6Uza5OK0WPqPKYZoYnAGQ19AOvrIVLRs0O0Ux6YaILjgU97y5lVqAG8LobztiaC7O0s54jiYw5eAcW94-EdzLNyPotxbLspSVjGOoc4DAou-jZ7zKgVvWWOKr6L8yRPbl93waH1AWYsvoYyhKau_is6o4GbQg0XDyGPKuB-ls92hk15tk81ckEmLHX0bkXv4c1mkzbYANpegvFIByW368MfIW7z1zatdFljgng_kCTEGKMPbnEkJy7EekYOniY61jEMBuhZK94zt7WpyV5-8qUhh2uPMgCq2MXAJ0MfeBjIcwff7Sic37gYqP1qUxmoaicV6D7Pbb8Tu3r9wLNMek6tufZPyMWerKfifgBuPrSO1xlL1v0Hn85wJVrdB1EgvGJVrLXB9NY7J2U1uL6Txef262J8wrAd3yk0YP7ils62SnwqbuctR5Xl4_-KhhYWR63EC2c7N41f56ge0-nj4eiDcr2N7VOkp6W22vMI-ahGuBZu6TjocQjq1JH_g7Vs">livk</a><img src="https://images.unsplash.com/photo-1580274455191-1c62238fa333?fm=jpg&amp;q=60&amp;w=3000&amp;auto=format&amp;fit=crop&amp;ixlib=rb-4.1.0&amp;ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D" alt="Porsche 911 noire sur la route pendant la journée" width="3000" height="3750"></p><p>Tuần này, <strong>Cinesphere</strong> hân hạnh mang đến cho quý khán giả siêu phẩm điện ảnh về đề tài cá mập sát thủ – một trải nghiệm thị giác và âm thanh đỉnh cao sẽ khiến bạn phải bám chặt vào ghế ngồi.</p><p><strong>Cốt truyện kịch tính đến nghẹt thở</strong> Bộ phim xoay quanh một nhóm thám hiểm vô tình lạc vào vùng biển bị lãng quên, nơi một thực thể cổ đại – loài cá mập trắng khổng lồ với kích thước không tưởng – đang thống trị. Không còn là những thợ săn, con người giờ đây trở thành con mồi trong trò chơi sinh tồn tàn khốc giữa lòng đại dương sâu thẳm.</p><p><strong>Tại sao bạn phải xem bộ phim này tại Cinesphere?</strong></p><ul><li data-list-item-id="e51c241b57b9fb1dcfedf65b602ab157f"><strong>Kỹ xảo CGI bậc thầy:</strong> Từng nhịp thở, từng cái quẫy đuôi của "quái vật đại dương" được tái hiện chân thực đến mức khó tin.</li></ul><p>&nbsp;</p><ul><li data-list-item-id="e487d646acbbdef401b59275ecaaf0026"><strong>Hệ thống âm thanh vòm:</strong> Bạn sẽ nghe thấy tiếng nước rẽ sóng ngay sát bên tai, tạo cảm giác như chính mình đang lênh đênh giữa biển khơi.</li><li data-list-item-id="eacbe7751beb0d1d5a0f62c7cf0a33c7a"><strong>Dữ liệu thực tế:</strong> Theo hệ thống <strong>AI Analytics</strong> của chúng tôi, đây là bộ phim có tỷ lệ khách hàng đặt lại vé lần 2 cao nhất trong tháng, đặc biệt là các nhóm bạn trẻ yêu thích cảm giác mạnh.</li></ul><p><strong>Ưu đãi đặc quyền khi đặt vé trực tuyến</strong> Để hành trình khám phá đại dương thêm trọn vẹn, Cinesphere dành tặng ưu đãi đặc biệt:</p><ol><li data-list-item-id="e03c43bfdf75af240e0b182f275deae63"><strong>Gói vé linh hoạt:</strong> Sử dụng gói <strong>"Vé 1 người"</strong> chỉ với <strong>536.000 VNĐ</strong> (đang là gói bán chạy nhất năm 2026 với 44 lượt đặt) để nhận ngay vị trí ngồi đẹp nhất.</li><li data-list-item-id="ea41f85fcaa4bfc3b5636a3de8cdc0226"><strong>Combo bắp nước:</strong> Giảm ngay 10% khi mua kèm các gói Combo tại quầy khi xuất trình mã booking từ website.</li></ol><p><strong>Đừng để nỗi sợ ngăn cản bạn!</strong> Số lượng suất chiếu khung giờ vàng đang vơi đi rất nhanh. Hãy truy cập ngay mục <strong>Đặt vé</strong> trên website, chọn chỗ ngồi ưng ý và chuẩn bị cho một chuyến phiêu lưu không thể nào quên.</p><p><i>Lưu ý: Phim có nhiều cảnh quay giật gân, khuyến cáo khán giả cân nhắc trước khi xem.</i></p>', 'Đừng xuống nước nếu bạn chưa sẵn sàng đối mặt với nỗi sợ nguyên thủy nhất. Theo chân nhóm thám hiểm đối đầu với thực thể thống trị đại dương trong cuộc chiến sinh tồn nghẹt thở. Phim đang dẫn đầu lượt đặt vé tại Cinesphere!', '/uploads/posts/1775031856789_jti0mq.webp', NULL, 'published', 1, 10, '2026-04-01T01:31:34.507Z', '2026-04-01T01:24:16.791Z', '2026-04-02T08:09:23.252Z');
INSERT INTO posts (id, title, slug, content, excerpt, featured_image, author_id, status, is_featured, view_count, published_at, created_at, updated_at) VALUES (1, 'Điểm mặt những "siêu phẩm" thống trị phòng vé Cinesphere tuần qua', 'iem-mat-nhung-sieu-pham-thong-tri-phong-ve-cinesphere-tuan-qua', '<p>Dựa trên số liệu phân tích từ hệ thống <strong>AI Analytics</strong> của chúng tôi, tuần này chứng kiến một sự bùng nổ chưa từng có tại phòng vé. Đứng đầu danh sách không ai khác chính là các bộ phim bom tấn đang làm mưa làm gió với tỷ lệ lấp đầy ghế luôn ở mức trên <strong>85%</strong>.</p><ol><li data-list-item-id="e79406b4f8ccd69d1c69d347d6e62fe9b"><strong>Lý do phim hot:</strong> Không chỉ sở hữu kỹ xảo mãn nhãn, các bộ phim này còn thu hút lượng lớn khách hàng sử dụng gói <strong>"Vé 1 người"</strong> - gói vé đang dẫn đầu về doanh thu với hơn <strong>44 lượt đặt</strong> trong thời gian ngắn.</li><li data-list-item-id="e0424189d4303f15796d372d35621eef7"><img class="image_resized" style="aspect-ratio:960/1280;width:50%;" src="/uploads/posts/posts_editor/1775030561677_1766992680476_keaylj.webp" width="960" height="1280"></li><li data-list-item-id="eff22d7c4288ab29df413e2830efdd184"><strong>Trải nghiệm đi kèm:</strong> Đa số khán giả đều lựa chọn kết hợp cùng các combo bắp nước đa dạng để nâng tầm trải nghiệm điện ảnh tại phòng chiếu duy nhất của chúng tôi.</li><li data-list-item-id="ede99198911f52d2444aefdbe62fd3a47"><strong>Lời khuyên:</strong> Với tốc độ đặt vé nhanh chóng như hiện tại, các suất chiếu khung giờ vàng thường hết chỗ rất sớm. Hãy truy cập ngay hệ thống <strong>CTBooking</strong> để giữ chỗ cho mình và bạn bè nhé!</li></ol>', 'Điểm mặt những "siêu phẩm" thống trị phòng vé Cinesphere tuần qua', '/uploads/posts/1775027494944_gwps05.webp', NULL, 'published', 0, 4, '2026-04-01T00:48:26.023Z', '2026-04-01T00:11:34.946Z', '2026-04-01T01:12:28.813Z');
